<template>
  <div class="tami-card-item" :class="{ '-active' : isCardFlipped }">
    <div class="tami-card-item__side -front">
      <div
          class="tami-card-item__focus"
          :class="{'-active' : focusElementStyle }"
          :style="focusElementStyle"
          ref="focusElement"
      ></div>
      <div class="tami-card-item__cover">
      </div>
      <div class="tami-card-item__wrapper">
        <label :for="fields.cardNumber" class="tami-card-item__number" :ref="fields.cardNumber">
          <template>
            <span v-for="(n, $index) in currentPlaceholder" :key="$index">
              <transition name="tami-slide-fade-up">
                <div class="tami-card-item__numberItem" v-if="getIsNumberMasked($index, n)">*</div>
                <div
                    class="tami-card-item__numberItem"
                    :class="{ '-active' : n.trim() === '' }"
                    :key="currentPlaceholder"
                    v-else-if="labels.cardNumber.length > $index"
                >{{ labels.cardNumber[$index] }}</div>
                <div
                    class="tami-card-item__numberItem"
                    :class="{ '-active' : n.trim() === '' }"
                    v-else
                    :key="currentPlaceholder + 1"
                >{{ n }}</div>
              </transition>
            </span>
          </template>
        </label>
        <div class="tami-card-item__content">
          <label :for="fields.cardName" class="tami-card-item__info" :ref="fields.cardName">
            <div class="tami-card-item__holder">{{ $t('card.cardHolder') }}</div>
            <transition name="tami-slide-fade-up">
              <div class="tami-card-item__name" v-if="labels.cardName.length" key="1">
                <transition-group name="tami-slide-fade-right">
                  <span
                      class="tami-card-item__nameItem"
                      v-for="(n, $index) in labels.cardName.replace(/\s\s+/g, ' ')"
                      :key="$index + 1"
                  >{{ n }}</span>
                </transition-group>
              </div>
              <div class="tami-card-item__name" v-else key="2">{{ $t('card.fullName') }}</div>
            </transition>
          </label>
          <div class="tami-card-item__date" ref="cardDate">
            <label :for="fields.cardMonth" class="tami-card-item__dateTitle">{{ $t('card.expires') }}</label>
            <label :for="fields.cardMonth" class="tami-card-item__dateItem">
              <transition name="tami-slide-fade-up">
                <span v-if="labels.cardMonth" :key="labels.cardMonth">{{ labels.cardMonth }}</span>
                <span v-else key="2">{{ $t('card.MM') }}</span>
              </transition>
            </label>
            /
            <label for="cardYear" class="tami-card-item__dateItem">
              <transition name="tami-slide-fade-up">
                <span v-if="labels.cardYear" :key="labels.cardYear">{{ String(labels.cardYear).slice(2, 4) }}</span>
                <span v-else key="2">{{ $t('card.YY') }}</span>
              </transition>
            </label>
          </div>

          <div class="tami-card-item__brand">
            <div class="tami-card-item__type">
              <transition name="slide-fade-up">
                <img
                    :src="require('./../assets/images/' + cardType + '.png')"
                    v-if="cardType"
                    :key="cardType"
                    alt
                    class="tami-card-item__typeImg"
                />
              </transition>
            </div>
          </div>

        </div>
      </div>
    </div>
    <div class="tami-card-item__side -back">
      <div class="tami-card-item__cover"></div>
      <div class="tami-card-item__band"></div>
      <div class="tami-card-item__cvv">
        <div class="tami-card-item__cvvTitle">CVV</div>
        <div class="tami-card-item__cvvBand">
          <span v-for="(n, $index) in labels.cardCvv" :key="$index">*</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'Card',
  props: {
    labels: Object,
    fields: Object,
    isCardNumberMasked: Boolean,
    randomBackgrounds: {
      type: Boolean,
      default: true
    },
    backgroundImage: [String, Object]
  },
  data () {
    return {
      focusElementStyle: null,
      currentFocus: null,
      isFocused: false,
      isCardFlipped: false,
      amexCardPlaceholder: '#### ###### #####',
      dinersCardPlaceholder: '#### ###### ####',
      defaultCardPlaceholder: '#### #### #### ####',
      currentPlaceholder: ''
    }
  },
  watch: {
    currentFocus () {
      if (this.currentFocus) {
        this.changeFocus()
      } else {
        this.focusElementStyle = null
      }
    },
    cardType () {
      this.changePlaceholder()
    }
  },
  mounted () {
    this.changePlaceholder()

    let self = this
    let fields = document.querySelectorAll('[data-card-field]')
    fields.forEach(element => {
      element.addEventListener('focus', () => {
        this.isFocused = true
        if (element.id === this.fields.cardYear || element.id === this.fields.cardMonth) {
          this.currentFocus = 'cardDate'
        } else {
          this.currentFocus = element.id
        }
        this.isCardFlipped = element.id === this.fields.cardCvv
      })
      element.addEventListener('blur', () => {
        this.isCardFlipped = !element.id === this.fields.cardCvv
        setTimeout(() => {
          if (!self.isFocused) {
            self.currentFocus = null
          }
        }, 300)
        self.isFocused = false
      })
    })
  },
  computed: {
    cardType () {
      let number = this.labels.cardNumber
      let re = new RegExp('^4')
      if (number.match(re) != null) return 'visa'

      re = new RegExp('^(34|37)')
      if (number.match(re) != null) return 'amex'

      re = new RegExp('^5[1-5]')
      if (number.match(re) != null) return 'mastercard'

      re = new RegExp('^6011')
      if (number.match(re) != null) return 'discover'

      re = new RegExp('^62')
      if (number.match(re) != null) return 'unionpay'

      re = new RegExp('^9792')
      if (number.match(re) != null) return 'troy'

      re = new RegExp('^3(?:0([0-5]|9)|[689]\\d?)\\d{0,11}')
      if (number.match(re) != null) return 'dinersclub'

      re = new RegExp('^35(2[89]|[3-8])')
      if (number.match(re) != null) return 'jcb'

      return '' // default type
    }
  },
  methods: {
    changeFocus () {
      let target = this.$refs[this.currentFocus]
      this.focusElementStyle = target ? {
        width: `${(target.offsetWidth) - 10}px`,
        height: `${(target.offsetHeight) - 10}px`,
        transform: `translateX(${(target.offsetLeft) + 5}px) translateY(${(target.offsetTop) + 5}px)`
      } : null
    },
    getIsNumberMasked (index, n) {
      return index > 4 && index < 14 && this.labels.cardNumber.length > index && n.trim() !== '' && this.isCardNumberMasked
    },
    changePlaceholder () {
      if (this.cardType === 'amex') {
        this.currentPlaceholder = this.amexCardPlaceholder
      } else if (this.cardType === 'dinersclub') {
        this.currentPlaceholder = this.dinersCardPlaceholder
      } else {
        this.currentPlaceholder = this.defaultCardPlaceholder
      }
      this.$nextTick(() => {
        this.changeFocus()
      })
    }
  }
}
</script>
